const inp = $input.first().json;
const text = String(inp.text == null ? '' : inp.text);
const mode = inp.mode === 'output' ? 'output' : 'input';
const source = String(inp.source || 'unknown');
let lower = text.toLowerCase();
lower = lower.replace(/\b(?:[a-z][\s.\-_]){3,}[a-z]\b/g, (m) => m.replace(/[\s.\-_]/g, ''));
const reasons = [];
const pii = [];

const injection = [
  [/ignore\s+(all\s+|any\s+)?(the\s+)?(previous|prior|above|earlier)\s+(instructions?|rules|prompts?)/, 'ignore-previous-instructions'],
  [/(ignore|disregard|forget)\s+(all\s+)?(your|the|these)\s+(rules|instructions|guidelines)/, 'ignore-your-rules'],
  [/disregard\s+(all\s+|any\s+)?(the\s+)?(previous|prior|above)/, 'disregard-previous'],
  [/(set\s+aside|forget|drop|discard|dismiss|abandon)\s+(about\s+)?(everything|all|anything)\s+(that\s+)?(you|your|i|we|was|were)/, 'paraphrase-forget'],
  [/(just\s+)?do\s+(exactly\s+)?what\s+i\s+(say|tell|command)/, 'obey-me'],
  [/(reveal|show|print|repeat|display|leak)\s+(me\s+)?(your|the)\s+(system\s+)?(prompt|instructions)/, 'reveal-prompt'],
  [/reply\s+with\s+.{0,40}\b(hacked|is_task)\b/, 'forced-output'],
  [/score\s+(this\s+candidate|me|them)\s+(as\s+)?100/, 'forced-score'],
  [/\b(developer|jailbreak|dan)\s+mode\b/, 'jailbreak-mode'],
  [/override\s+(the\s+)?(system|safety|your)\s*(rules|prompt|instructions)?/, 'override-system'],
  [/\bnew\s+instructions?\s*:/, 'new-instructions'],
  [/you\s+are\s+now\s+(a|an|in)\b/, 'role-switch'],
  [/(nirdesh|instructions?|rules?|niyam)\s+(sab\s+|saare\s+|saari\s+)?(bhool|bhul|ignore)/, 'hinglish-forget'],
  [/(pichhle|pehle\s+ke|purane)\s+(saare\s+)?(nirdesh|instructions?|niyam)/, 'hinglish-previous'],
  [/(ignore|bhool)\s+(karo|jao|do)\b.{0,30}(instructions?|nirdesh|rules?)/, 'hinglish-ignore']
];
if (mode === 'input') {
  for (const [re, name] of injection) { if (re.test(lower)) reasons.push('injection:' + name); }
}

if (mode === 'output') {
  if (/\bsk-[a-z0-9_-]{16,}/i.test(text)) reasons.push('leak:api-key');
  if (/(api[ _-]?key|secret|password|token)\s*[:=]\s*\S{6,}/i.test(text)) reasons.push('leak:credential');
  if (/(my|the)\s+system\s+prompt\s+(is|says)/i.test(text)) reasons.push('leak:system-prompt');
}

function luhn(digits) {
  let sum = 0, alt = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let n = Number(digits[i]);
    if (alt) { n *= 2; if (n > 9) n -= 9; }
    sum += n; alt = !alt;
  }
  return sum % 10 === 0;
}
let clean = text;
clean = clean.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, () => { pii.push('email'); return '[EMAIL]'; });
clean = clean.replace(/[A-Za-z0-9._%+-]+\s*(?:\[at\]|\(at\)|\sat\s)\s*[A-Za-z0-9-]+\s*(?:\[dot\]|\(dot\)|\sdot\s)\s*[A-Za-z]{2,}/gi, () => { pii.push('email'); return '[EMAIL]'; });
clean = clean.replace(/\b(?:\d[ -]?){13,16}\b/g, (m) => {
  const d = m.replace(/[^0-9]/g, '');
  if (d.length >= 13 && d.length <= 16 && luhn(d)) { pii.push('card'); return '[CARD]'; }
  return m;
});
clean = clean.replace(/\b\d{4}[ -]?\d{4}[ -]?\d{4}\b/g, () => { pii.push('aadhaar'); return '[AADHAAR]'; });
clean = clean.replace(/\b[A-Z]{5}\d{4}[A-Z]\b/g, () => { pii.push('pan'); return '[PAN]'; });
clean = clean.replace(/(?:\+91[ -]?|\b0)?\b[6-9]\d{4}[ -]?\d{5}\b/g, () => { pii.push('phone'); return '[PHONE]'; });
clean = clean.replace(/(?:\+91[ -]?|\b0)?\b[6-9]\d{9}\b/g, () => { pii.push('phone'); return '[PHONE]'; });
clean = clean.replace(/\+\d{1,3}[ -]?\d{2,4}[ -]?\d{3,4}[ -]?\d{3,4}\b/g, () => { pii.push('phone'); return '[PHONE]'; });

let verdict = 'allow';
if (reasons.length) verdict = 'block';
else if (pii.length) { verdict = 'redact'; reasons.push('pii:' + Array.from(new Set(pii)).join(',')); }
if (verdict === 'block' && pii.length) reasons.push('pii:' + Array.from(new Set(pii)).join(','));

return [{ json: {
  verdict,
  reasons,
  clean_text: verdict === 'block' ? '' : clean,
  pii_found: Array.from(new Set(pii)),
  mode,
  source,
  length: text.length
} }];
